        step = input('key is exist, do you want generate new key?(y/n):')
        while True:
            if step in ('y', 'Y'):
                generate_key()
                print('new key generated')
                break
            elif step in ('n', 'N'):
                print('exit')
                break
            else:
                step = input('please input (y/n):')
                continue
    else:
