import weakref


class Meta(type):
    _inst = weakref.WeakSet()

    def connect(cls, *args, **kwargs):
        _args = {}
        if len(args) > 2:
            _args.update({'a': args[-1]})
            _args.update({'args': args[:-1]})
        else:
            _args.update({'args': args})
            _args.update(kwargs)
        if cls == SiamObj:
            for i in cls._inst:
                if i.__dict__ == _args:
                    return i

    @staticmethod
    def args_collector(inst, *args, **kwargs):
        for key, value in kwargs.items():
            inst.__dict__[key] = value
        if len(args) > 2:
            inst.__dict__.update({'a': args[-1]})
            inst.__dict__.update({'args': args[:-1]})
        else:
            inst.__dict__.update({'args': args})

    def __call__(cls, *args, **kwargs):
        setattr(cls, 'connect', cls.connect)
        setattr(cls, 'pool', cls._inst)
        _cls = super().__call__(*args, **kwargs)
        cls.args_collector(_cls, *args, **kwargs)
        for item in cls._inst:
            if type(item) != type(_cls):
                cls._inst.add(_cls)
        if isinstance(_cls, SiamObj):
            for i in cls._inst:
                if i.__dict__ == _cls.__dict__:
                    return i
            cls._inst.add(_cls)
        for i, item in enumerate(cls._inst):
            if i == len(cls._inst)-1:
                return item


class SiamObj(metaclass=Meta):
    def __init__(self, *args, **kwargs):
        pass


