import pandas as pd
import random
from collections import Counter

PROB_MASK_NON_KEYWORDS = 0.9

PROB_KEEP_KEYWORDS = 0.8
PROB_REPLACE_KEYWORDS = 0.15
PROB_MASK_KEYWORDS = 0.05

class MaskCorpus():

    def __init__(self,
                 corpus,
                 idx,
                 keep_tags,
                 keep_words):

        self.keep_tags=keep_tags
        self.keep_words=keep_words
        self.corpus=corpus
        self.idx=idx
        self.tagger=self._default_tagger()
        self.vocab=self.build_vocab(corpus)

    def build_vocab(self, corpus):
        vocab = Counter()
        for sentence in corpus:
            vocab += Counter(sentence.split())
        return list(vocab)

    def _default_tagger(self):
        try:
            import spacy_udpipe
        except ImportError:
            raise('You are missing pos tagger, try `pip install spacy_udpipe`')
        spacy_udpipe.download('en')
        return spacy_udpipe.load('en')

    def _mask_non_keywords(self, word):
        return '[MASK]' if random.random()<PROB_MASK_NON_KEYWORDS else word

    def _mask_keywords(self, word):
        choice = random.random()
        if choice < PROB_KEEP_KEYWORDS:
            return word
        elif PROB_KEEP_KEYWORDS<=choice and choice<PROB_REPLACE_KEYWORDS+PROB_KEEP_KEYWORDS:
            return random.sample(self.vocab, 1)[0]
        else:
            return '[MASK]'

    def generate_corpus(self):
        masked_corpus = []
        for id, sentence in zip(self.idx, self.corpus):
            _sentence = self.tagger(sentence.lower())
            masked_sentence = []
            original_sentence = []
            for token in _sentence:
                if (token.text not in self.keep_words) and \
                    (token.pos_ not in self.keep_tags):
                    masked_sentence.append(self._mask_non_keywords(token.text))
                elif token.text in self.keep_words:
                    masked_sentence.append(token.text)
                else:
                    masked_sentence.append(self._mask_keywords(token.text))
                original_sentence.append(token.text)
            masked_corpus.append((id, ' '.join(masked_sentence), ' '.join(original_sentence)))
        return masked_corpus

import sys
from datetime import datetime
from BaseDetector import BaseDetector


# SilentTestDetector never detect
class SilentTestDetector(BaseDetector):
    def __init__(self):
        BaseDetector.__init__(self)
        self.detectorName = 'SilentDetector'

    def execute(self):
        BaseDetector.execute(self)

# AlertingTestDetector always detect
class AlertingTestDetector(BaseDetector):
    def __init__(self, priority = 'DEBUG'):
        BaseDetector.__init__(self, priority)
        self.detectorName = 'AlertingDetector'
    def execute(self):
        BaseDetector.execute(self)
        timestamp = datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S.%f')[:-3]
        detectionTime = timestamp
        description = ''
        name = self.detectorName
        priority = self.priority
        body = ''

        BaseDetector.sendAlarm(self,timestamp, name, priority, description, detectionTime, body)

# HaltingTestDetector never returns
class HaltingTestDetector(BaseDetector):
    def __init__(self):
        BaseDetector.__init__(self)
        self.detectorName = 'HaltingDetector'
    def execute(self):
        BaseDetector.execute(self)
        while True:
            pass

# RaiseErrorDetector always fails with code error, returns -1
class RaiseErrorTestDetector(BaseDetector):
    def __init__(self):
        BaseDetector.__init__(self)
        self.detectorName = 'RaiseErrorDetector'

    def execute(priorityself):
        BaseDetector.execute(self)
        raise Exception('Error Raiser for ErrorRaiserDetector')

def main(args):
    detectorName = args[0]
    # print detectorName

    priority = None
    if len(args) > 1:
        priority = args[1]

    if detectorName == 'SilentDetector':
        myDetector = SilentTestDetector()
    elif detectorName == 'AlertingDetector':
        myDetector = AlertingTestDetector(priority)
    elif detectorName == 'HaltingDetector':
        myDetector = HaltingTestDetector()
    elif detectorName == 'RaiseErrorDetector':
        myDetector = RaiseErrorTestDetector()

    myDetector.execute()


if __name__ == '__main__':
    # print sys.argv[1:]
    main(sys.argv[1:])

from random import choice, randint

from .roll import roll
from .region_tables import region_populations, region_names

def rollMultipleDays(num_days, region, density):
    days = []
    for i in range(1, num_days+1):
        daily_encounters = rollDay(region, density)
        if len(daily_encounters):
            days.append( ('Day {}'.format(i), daily_encounters))

    return days

def rollDay(region, density):
    if density == 'Dense':
        die = 20
    elif density == 'Sparse':
        die = 12
    else:
        die = 10

    if 'Plains' in region:
        enc = checkDailyEncounters(region, die,
            ('Morning','Evening','Midnight'))
    elif 'Scrub' in region:
        reg = region.replace('Scrub', 'Plains')
        enc = checkDailyEncounters(reg, die,
            ('Morning','Evening','Night','Pre-Dawn'))
    elif 'Forest' in region:
        enc = checkDailyEncounters(region, die,
            ('Morning','Noon','Evening','Night','Midnight','Pre-Dawn'))
    elif 'Desert' in region:
        enc = checkDailyEncounters(region, die,
            ('Morning','Night','Pre-Dawn'))
    elif 'Hills' in region:
        enc = checkDailyEncounters(region, die,
            ('Noon','Night','Pre-Dawn'))
    elif 'Mountains' in region:
        enc = checkDailyEncounters(region, die,
            ('Morning','Night'))
    elif 'Marsh' in region or 'Swamp' in region:
        enc = checkDailyEncounters(region, die,
            ('Morning','Noon','Evening','Night','Midnight','Pre-Dawn'))
    else:
        raise ValueError

    return enc

def checkDailyEncounters(region, die, time_list):
    encounters = []
    for t in time_list:
        r = roll(die)
        if r == 1:
            e = pickEncounterInRegion(region)
            encounters.append( (t,e) )
    return encounters

def pickEncounterInRegion(region):
    r = roll(12) + roll(8)
    encounter_list = []

    if (8 < r < 14):
        encounter_list = region_populations[region].C
    elif (r == 7 or r == 8 or r == 14 or r == 15):
        encounter_list = region_populations[region].UC
    elif (r == 5 or r == 6 or r == 16 or r == 17):
        encounter_list = region_populations[region].R
    elif (r == 4) or (r == 18):
        r = roll(2)
        if r == 1: encounter_list = region_populations[region].VR
        else: encounter_list = region_populations[region].R
    elif (r < 4) or (r > 18):
        encounter_list = region_populations[region].VR

    return choice(encounter_list)

def classicRandomEncounter(region):
    r = roll(12) + roll(8)
    r -= 2
    encounter_list = regions[region]
    return encounter_list[r]

