    )


def get_cases_by_shard(cases, selected_shard, total_shards, verbosity, stats):
    if total_shards <= 1:
        return cases

    selected_shard -= 1  # starting from 0
    new_test_est = 0.1  # default estimate if test is not found in stats
    new_setup_est = 1  # default estimate if setup is not found in stats

    # For logging
    total_tests = 0
    selected_tests = 0
    total_est = 0
    selected_est = 0

    # Priority queue of tests grouped by setup script ordered by estimated
    # running time of the groups. Order of tests within cases is preserved.
    tests_by_setup = []

    # Priority queue of individual tests ordered by estimated running time.
    tests_with_est = []

    # Prepare the source heaps
    setup_count = 0
    for case, tests in cases.items():
        setup_script = getattr(case, 'get_setup_script', lambda: None)()
        if setup_script and tests:
            tests_per_setup = []
            est_per_setup = setup_est = stats.get(
                'setup::' + case.get_database_name(), (new_setup_est, 0),
            )[0]
            for test in tests:
                total_tests += 1
                est = stats.get(str(test), (new_test_est, 0))[0]
                est_per_setup += est
                tests_per_setup.append((est, test))
            heapq.heappush(
                tests_by_setup,
                (-est_per_setup, setup_count, setup_est, tests_per_setup),
            )
            setup_count += 1
            total_est += est_per_setup
        else:
            for test in tests:
                total_tests += 1
                est = stats.get(str(test), (new_test_est, 0))[0]
                total_est += est
                heapq.heappush(tests_with_est, (-est, total_tests, test))

    target_est = total_est / total_shards  # target running time of one shard
    shards_est = [(0, shard, set()) for shard in range(total_shards)]
    cases = {}  # output
    setup_to_alloc = set(range(setup_count))  # tracks first run of each setup

    # Assign per-setup tests first
    while tests_by_setup:
        remaining_est, setup_id, setup_est, tests = heapq.heappop(
            tests_by_setup,
        )
        est_acc, current, setups = heapq.heappop(shards_est)

        # Add setup time
        if setup_id not in setups:
            setups.add(setup_id)
            est_acc += setup_est
            if current == selected_shard:
                selected_est += setup_est
            if setup_id in setup_to_alloc:
                setup_to_alloc.remove(setup_id)
            else:
                # This means one more setup for the overall test run
                target_est += setup_est / total_shards

        # Add as much tests from this group to current shard as possible
        while tests:
            est, test = tests.pop(0)
            est_acc += est  # est is a positive number
            remaining_est += est  # remaining_est is a negative number

            if current == selected_shard:
                # Add the test to the result
                _add_test(cases, test)
                selected_tests += 1
                selected_est += est

            if est_acc >= target_est and -remaining_est > setup_est * 2:
                # Current shard is full and the remaining tests would take more
                # time than their setup, then add the tests back to the heap so
                # that we could add them to another shard
                heapq.heappush(
                    tests_by_setup,
                    (remaining_est, setup_id, setup_est, tests),
                )
                break

        heapq.heappush(shards_est, (est_acc, current, setups))

    # Assign all non-setup tests, but leave the last shard for everything else
    setups = set()
    while tests_with_est and len(shards_est) > 1:
        est, _, test = heapq.heappop(tests_with_est)  # est is negative
        est_acc, current, setups = heapq.heappop(shards_est)
        est_acc -= est

        if current == selected_shard:
            # Add the test to the result
            _add_test(cases, test)
            selected_tests += 1
            selected_est -= est

        if est_acc >= target_est:
            # The current shard is full
            if current == selected_shard:
                # End early if the selected shard is full
                break
        else:
            # Only add the current shard back to the heap if it's not full
            heapq.heappush(shards_est, (est_acc, current, setups))

    else:
        # Add all the remaining tests to the first remaining shard if any
        while shards_est:
            est_acc, current, setups = heapq.heappop(shards_est)
            if current == selected_shard:
                for est, _, test in tests_with_est:
                    _add_test(cases, test)
                    selected_tests += 1
                    selected_est -= est
                break
            tests_with_est.clear()  # should always be empty already here

    if verbosity >= 1:
        print(f'Running {selected_tests}/{total_tests} tests for shard '
              f'#{selected_shard + 1} out of {total_shards} shards, '
              f'estimate: {int(selected_est / 60)}m {int(selected_est % 60)}s'
              f' / {int(total_est / 60)}m {int(total_est % 60)}s, '
              f'{len(setups)}/{setup_count} databases to setup.')
    return cases


def find_available_port():
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    try:
        sock.bind(("localhost", 0))
        return sock.getsockname()[1]
    finally:
        sock.close()

class BedReader(object):
    """
    Simple class to ingest BED files and return a data structure as such:
    {chrom: [start1, stop1], [start2, stop2], ...}

    Input: filename
    """

    def __init__(self, filename):

        self.filename = open(filename, 'rU')
        self.bed_ints = self._create_bed()
        self.chrom_list = list(self.bed_ints)

    def _create_bed(self):

        """
        Create the structure of BED coordinates connected to chromosome
        identifiers.
        Return start and stop in 1-based coords.
        :return bed_ints:
        """
        bed_ints = {}
        with self.filename as bed:
            for interval in bed:
                interval = interval.rstrip('\n').split('\t')
                chrom = str(interval[0])
                # 0-based
                start = int(interval[1])+1
                # 1-based
                stop = int(interval[2])

                if chrom not in bed_ints:
                    bed_ints[chrom] = [[start, stop]]
                else:
                    bed_ints[chrom].append([start, stop])
        return bed_ints


    def split_coords(self):
        """
        Split out the intervals in to single coords.
        :return:
        """
        split_coords = {}
        for chrom in self.bed_ints:
            split_coords[chrom] = []
            for coords in self.bed_ints[chrom]:
                for coord in range(coords[0], coords[1]+1):
                    split_coords[chrom].append(coord)

        return split_coords


class ExtBedReader(object):
    """

    """
    def __init__(self, filename, header=False, hgnc=False, strand=False,
                 phase=False, pstart=False, pstop=False):
#        super(ExtBedReader, self).__init__(*args, **kwargs)
        self.filename = open(filename, 'rU')
        self.header = header
        self.hgnc = hgnc
        self.strand = strand
        self.phase = phase
        self.pstart = pstart
        self.pstop = pstop
        self.bed_ints = self._ext_bed_parse()

    def _ext_bed_parse(self):
        """
        Provide additional BED information for use.
        :return:
        """
        ext_bed_ints = {}
        with self.filename as bed:
            if self.header:
                next(bed)
            for interval in bed:
                interval = interval.rstrip('\n').split('\t')
                chrom = str(interval[0])
                if chrom.startswith('chr'):
                    chrom = chrom[3:]

                if chrom not in ext_bed_ints:
                    ext_bed_ints[chrom] = {}

                # 0-based
                start = int(interval[1]) + 1
                # 1-based
                stop = int(interval[2])

                new_key = (str(start), str(stop))
                ext_bed_ints[chrom][new_key] = {}
                ext_bed_ints[chrom][new_key]['start'] = start
                ext_bed_ints[chrom][new_key]['stop'] = stop

                if self.hgnc:
                    ext_bed_ints[chrom][new_key]['hgnc'] = interval[self.hgnc]
                if self.strand:
                    if interval[self.strand] == '-':
                        interval[self.strand] = 0
                    elif interval[self.strand] == '+':
                        interval[self.strand] = 1
                    ext_bed_ints[chrom][new_key]['strand'] = interval[self.strand]
                if self.phase:
                    ext_bed_ints[chrom][new_key]['phase'] = interval[self.phase]
                if self.pstart:
                    ext_bed_ints[chrom][new_key]['pstart'] = int(interval[self.pstart])
                if self.pstop:
                    ext_bed_ints[chrom][new_key]['pstop'] = int(interval[self.pstop])

        return ext_bed_ints

    def find_primer_coords(self, tsize=250):
        """
        Based on a given region length, and BED coordinates, find the
        primer coords.
        :return:
        """
        primer_coords = {}
        for chrom in self.bed_ints:
            primer_coords[chrom] = []
            for entry in self.bed_ints[chrom].values():
                rsize = entry['stop'] - entry['start'] + 1
                psize = tsize - rsize
                if entry['strand'] == 0:
                    # Theses are being flipped, so that the start > stop for
                    #  primers targeting reverse strand seqs.
                    pstop = entry['stop'] + 1
                    pstart = entry['stop'] + psize + 1
                elif entry['strand'] == 1:
                    pstart = entry['start'] - psize
                    pstop = entry['start'] - 1
                else:
                    raise ValueError("The strand should either be 0 or 1.")

                primer_coords[chrom].append([pstart, pstop])

        return primer_coords


    def get_primer_ends(self):
        """
        This is an extended version of find_primer_coords, where we pull
        down just the coordinates that are near the ends.
        {CHROM: {STRAND: (a, b, c, ...)}}
        :return:
        """
        primer_coords = {}
        for chrom in self.bed_ints.keys():
            primer_coords[chrom] = {}
            for coord in self.bed_ints[chrom].values():
                strand = str(coord['strand'])
                if strand not in primer_coords[chrom]:
                    primer_coords[chrom][strand] = []

                if coord['strand'] == 0:
                    pstop = coord['stop'] + 1
                elif coord['strand'] == 1:
                    pstop = coord['start'] - 1
                else:
                    raise ValueError("The strand should either be 0 or 1.")

                primer_coords[chrom][strand].append(pstop)

        return primer_coords


    def get_v4_primer_ends(self):
        """
        This is an extended version of find_primer_coords, where we pull
        down just the coordinates that are near the ends.
        {CHROM: {STRAND: (a, b, c, ...)}}
        This will utilize pre-created values in final two columns of v4 BED.
        :return:
        """
        primer_coords = {}
        for chrom in self.bed_ints.keys():
            primer_coords[chrom] = {}
            for coord in self.bed_ints[chrom].values():
                strand = str(coord['strand'])
                if strand not in primer_coords[chrom]:
                    primer_coords[chrom][strand] = []

                if coord['strand'] == 0:
                    pstop = coord['pstop'] + 1
                elif coord['strand'] == 1:
                    pstop = coord['pstart'] - 1
                else:
                    raise ValueError("The strand should either be 0 or 1.")

                primer_coords[chrom][strand].append(pstop)

        return primer_coords

