import pandas as pd
import random
from collections import Counter

PROB_MASK_NON_KEYWORDS = 0.9

PROB_KEEP_KEYWORDS = 0.8
PROB_REPLACE_KEYWORDS = 0.15
PROB_MASK_KEYWORDS = 0.05

class MaskCorpus():

    def __init__(self,
                 corpus,
                 idx,
                 keep_tags,
                 keep_words):

        self.keep_tags=keep_tags
        self.keep_words=keep_words
        self.corpus=corpus
        self.idx=idx
        self.tagger=self._default_tagger()
        self.vocab=self.build_vocab(corpus)

    def build_vocab(self, corpus):
        vocab = Counter()
        for sentence in corpus:
            vocab += Counter(sentence.split())
        return list(vocab)

    def _default_tagger(self):
        try:
            import spacy_udpipe
        except ImportError:
            raise('You are missing pos tagger, try `pip install spacy_udpipe`')
        spacy_udpipe.download('en')
        return spacy_udpipe.load('en')

    def _mask_non_keywords(self, word):
        return '[MASK]' if random.random()<PROB_MASK_NON_KEYWORDS else word

    def _mask_keywords(self, word):
        choice = random.random()
        if choice < PROB_KEEP_KEYWORDS:
            return word
        elif PROB_KEEP_KEYWORDS<=choice and choice<PROB_REPLACE_KEYWORDS+PROB_KEEP_KEYWORDS:
            return random.sample(self.vocab, 1)[0]
        else:
            return '[MASK]'

    def generate_corpus(self):
        masked_corpus = []
        for id, sentence in zip(self.idx, self.corpus):
            _sentence = self.tagger(sentence.lower())
            masked_sentence = []
            original_sentence = []
            for token in _sentence:
                if (token.text not in self.keep_words) and \
                    (token.pos_ not in self.keep_tags):
                    masked_sentence.append(self._mask_non_keywords(token.text))
                elif token.text in self.keep_words:
                    masked_sentence.append(token.text)
                else:
                    masked_sentence.append(self._mask_keywords(token.text))
                original_sentence.append(token.text)
            masked_corpus.append((id, ' '.join(masked_sentence), ' '.join(original_sentence)))
        return masked_corpus

# byr (Birth Year)
# iyr (Issue Year)
# eyr (Expiration Year)
# hgt (Height)
# hcl (Hair Color)
# ecl (Eye Color)
# pid (Passport ID)
# cid (Country ID)

required_keys = {'byr', 'iyr', 'eyr', 'hgt', 'hcl', 'ecl', 'pid', 'cid'}
optional_keys = {'cid'}
filename = "./d4/input.txt"
passports = []

with open(filename) as f:
    passports = []
    passport = {}
    for line in f.readlines():
        if len(line.strip()) == 0:
            passports.append(passport)
            passport = {}
        else:
            fields = line.strip().split(' ')
            for field in fields:
                f, v = field.split(':')
                passport.update({f:v})

    if passports:
        passports.append(passport)

# byr (Birth Year) - four digits; at least 1920 and at most 2002.
# iyr (Issue Year) - four digits; at least 2010 and at most 2020.
# eyr (Expiration Year) - four digits; at least 2020 and at most 2030.
# hgt (Height) - a number followed by either cm or in:
# If cm, the number must be at least 150 and at most 193.
# If in, the number must be at least 59 and at most 76.
# hcl (Hair Color) - a # followed by exactly six characters 0-9 or a-f.
# ecl (Eye Color) - exactly one of: amb blu brn gry grn hzl oth.
# pid (Passport ID) - a nine-digit number, including leading zeroes.
# cid (Country ID) - ignored, missing or not.

def validate_passport(passport):

    def _check_valid_int(value, count, lb, ub):
        if len(value) != count:
            return False
        ivalue = int(value)
        if ivalue < lb or ivalue > ub:
            return False
        return True
    byr = passport['byr']
    if not _check_valid_int(byr, 4, 1920, 2002):
        return False

    iyr = passport['iyr']
    if not _check_valid_int(iyr, 4, 2010, 2020):
        return False

    eyr = passport['eyr']
    if not _check_valid_int(eyr, 4, 2020, 2030):
        return False


def count_valid(passports, required_keys, optional_keys):

    count = 0
    for p in passports:
        s = set(p.keys())
        if len(required_keys - optional_keys - s) == 0:
            count += 1
    return count

print(f'valid count: {count_valid(passports, required_keys, optional_keys)}')

