class PaymentProcessor(ProcessorBase):
    key = "paypal"
    default_name = _("Paypal")

    def get_urls(self):
        from django.conf.urls import url

        return [
            url(r"^payment/paypal/ipn/$", self.ipn, name="plata_payment_paypal_ipn")
