def rollMultipleDays(num_days, region, density):
    days = []
    for i in range(1, num_days+1):
        daily_encounters = rollDay(region, density)
        if len(daily_encounters):
            days.append( ('Day {}'.format(i), daily_encounters))

    return days

def rollDay(region, density):
    if density == 'Dense':
        die = 20
    elif density == 'Sparse':
        die = 12
    else:
        die = 10

    if 'Plains' in region:
        enc = checkDailyEncounters(region, die,
            ('Morning','Evening','Midnight'))
    elif 'Scrub' in region:
        reg = region.replace('Scrub', 'Plains')
        enc = checkDailyEncounters(reg, die,
            ('Morning','Evening','Night','Pre-Dawn'))
    elif 'Forest' in region:
        enc = checkDailyEncounters(region, die,
            ('Morning','Noon','Evening','Night','Midnight','Pre-Dawn'))
    elif 'Desert' in region:
        enc = checkDailyEncounters(region, die,
            ('Morning','Night','Pre-Dawn'))
    elif 'Hills' in region:
        enc = checkDailyEncounters(region, die,
            ('Noon','Night','Pre-Dawn'))
    elif 'Mountains' in region:
        enc = checkDailyEncounters(region, die,
            ('Morning','Night'))
    elif 'Marsh' in region or 'Swamp' in region:
        enc = checkDailyEncounters(region, die,
            ('Morning','Noon','Evening','Night','Midnight','Pre-Dawn'))
    else:
        raise ValueError

    return enc

def checkDailyEncounters(region, die, time_list):
    encounters = []
    for t in time_list:
        r = roll(die)
        if r == 1:
            e = pickEncounterInRegion(region)
            encounters.append( (t,e) )
    return encounters

def pickEncounterInRegion(region):
    r = roll(12) + roll(8)
    encounter_list = []

    if (8 < r < 14):
        encounter_list = region_populations[region].C
    elif (r == 7 or r == 8 or r == 14 or r == 15):
        encounter_list = region_populations[region].UC
    elif (r == 5 or r == 6 or r == 16 or r == 17):
        encounter_list = region_populations[region].R
    elif (r == 4) or (r == 18):
        r = roll(2)
        if r == 1: encounter_list = region_populations[region].VR
        else: encounter_list = region_populations[region].R
    elif (r < 4) or (r > 18):
        encounter_list = region_populations[region].VR

    return choice(encounter_list)

def classicRandomEncounter(region):
    r = roll(12) + roll(8)
    r -= 2
    encounter_list = regions[region]
    return encounter_list[r]

class AsynchronousRange:
    def __init__(self, fr, to=None, step=1):
        if to is None:
            self._iterator = iter(range(fr))
        else:
            self._iterator = iter(range(fr, to, step))

    def __aiter__(self):
        return self

    async def __anext__(self):
        try:
            return next(self._iterator)
        except StopIteration:
            raise StopAsyncIteration

class BedReader(object):
    """
    Simple class to ingest BED files and return a data structure as such:
    {chrom: [start1, stop1], [start2, stop2], ...}

    Input: filename
    """

    def __init__(self, filename):

        self.filename = open(filename, 'rU')
        self.bed_ints = self._create_bed()
        self.chrom_list = list(self.bed_ints)

    def _create_bed(self):

        """
        Create the structure of BED coordinates connected to chromosome
        identifiers.
        Return start and stop in 1-based coords.
        :return bed_ints:
        """
        bed_ints = {}
        with self.filename as bed:
            for interval in bed:
                interval = interval.rstrip('\n').split('\t')
                chrom = str(interval[0])
                # 0-based
                start = int(interval[1])+1
                # 1-based
                stop = int(interval[2])

                if chrom not in bed_ints:
                    bed_ints[chrom] = [[start, stop]]
                else:
                    bed_ints[chrom].append([start, stop])
        return bed_ints


    def split_coords(self):
        """
        Split out the intervals in to single coords.
        :return:
        """
        split_coords = {}
        for chrom in self.bed_ints:
            split_coords[chrom] = []
            for coords in self.bed_ints[chrom]:
                for coord in range(coords[0], coords[1]+1):
                    split_coords[chrom].append(coord)

        return split_coords


