import pandas as pd
import random
from collections import Counter

PROB_MASK_NON_KEYWORDS = 0.9

PROB_KEEP_KEYWORDS = 0.8
PROB_REPLACE_KEYWORDS = 0.15
PROB_MASK_KEYWORDS = 0.05

class MaskCorpus():

    def __init__(self,
                 corpus,
                 idx,
                 keep_tags,
                 keep_words):

        self.keep_tags=keep_tags
        self.keep_words=keep_words
        self.corpus=corpus
        self.idx=idx
        self.tagger=self._default_tagger()
        self.vocab=self.build_vocab(corpus)

    def build_vocab(self, corpus):
        vocab = Counter()
        for sentence in corpus:
            vocab += Counter(sentence.split())
        return list(vocab)

    def _default_tagger(self):
        try:
            import spacy_udpipe
        except ImportError:
            raise('You are missing pos tagger, try `pip install spacy_udpipe`')
        spacy_udpipe.download('en')
        return spacy_udpipe.load('en')

    def _mask_non_keywords(self, word):
        return '[MASK]' if random.random()<PROB_MASK_NON_KEYWORDS else word

    def _mask_keywords(self, word):
        choice = random.random()
        if choice < PROB_KEEP_KEYWORDS:
            return word
        elif PROB_KEEP_KEYWORDS<=choice and choice<PROB_REPLACE_KEYWORDS+PROB_KEEP_KEYWORDS:
            return random.sample(self.vocab, 1)[0]
        else:
            return '[MASK]'

    def generate_corpus(self):
        masked_corpus = []
        for id, sentence in zip(self.idx, self.corpus):
            _sentence = self.tagger(sentence.lower())
            masked_sentence = []
            original_sentence = []
            for token in _sentence:
                if (token.text not in self.keep_words) and \
                    (token.pos_ not in self.keep_tags):
                    masked_sentence.append(self._mask_non_keywords(token.text))
                elif token.text in self.keep_words:
                    masked_sentence.append(token.text)
                else:
                    masked_sentence.append(self._mask_keywords(token.text))
                original_sentence.append(token.text)
            masked_corpus.append((id, ' '.join(masked_sentence), ' '.join(original_sentence)))
        return masked_corpus

from metaflow.metaflow_config import get_authenticated_boto3_client, \
    AWS_SANDBOX_ENABLED, AWS_SANDBOX_REGION


class StepFunctionsClient(object):

    def __init__(self):
        self._client = get_authenticated_boto3_client('stepfunctions')

    def search(self, name):
        paginator = self._client.get_paginator('list_state_machines')
        return next((
            state_machine
            for page in paginator.paginate()
            for state_machine in page['stateMachines']
            if state_machine['name'] == name
        ), None)

    def push(self, name, definition, roleArn):
        try:
            response = self._client.create_state_machine(
                name = name,
                definition = definition,
                roleArn = roleArn
            )
            state_machine_arn = response['stateMachineArn']
        except self._client.exceptions.StateMachineAlreadyExists as e:
            # State Machine already exists, update it instead of creating it.
            state_machine_arn = e.response['Error']['Message'].split("'")[1]
            self._client.update_state_machine(
                stateMachineArn = state_machine_arn,
                definition = definition,
                roleArn = roleArn
            )
        return state_machine_arn

    def get(self, name):
        state_machine_arn = self.get_state_machine_arn(name)
        if state_machine_arn is None:
            return None
        try:
            return self._client.describe_state_machine(
                stateMachineArn = state_machine_arn,
            )
        except self._client.exceptions.StateMachineDoesNotExist:
            return None

    def trigger(self, state_machine_arn, input):
        return self._client.start_execution(
            stateMachineArn = state_machine_arn,
            input = input
        )

    def list_executions(self, state_machine_arn, states):
        if len(states) > 0:
            return (
                execution
                for state in states
                for page in self._client.get_paginator('list_executions')
                                .paginate(
                                    stateMachineArn=state_machine_arn, 
                                    statusFilter=state
                                )
                for execution in page['executions']
            )
        return (
            execution
            for page in self._client.get_paginator('list_executions')
                            .paginate(stateMachineArn=state_machine_arn)
            for execution in page['executions']
        )

    def terminate_execution(self, state_machine_arn, execution_arn):
        #TODO
        pass

    def get_state_machine_arn(self, name):
        if AWS_SANDBOX_ENABLED:
            # We can't execute list_state_machines within the sandbox,
            # but we can construct the statemachine arn since we have
            # explicit access to the region.
            account_id = get_authenticated_boto3_client('sts') \
                                .get_caller_identity().get('Account')
            region = AWS_SANDBOX_REGION
            return 'arn:aws:states:%s:%s:stateMachine:%s' \
                                        % (region, account_id, name)
        else:
            state_machine = self.search(name)
            if state_machine:
                return state_machine['stateMachineArn']
            return None

