            ('0', _('None'), ),
        )

    def queryset(self, request, queryset):

        kwargs = {
            self.parameter_name: u'' if self.is_charfield else None,
        }

        if self.value() == '0':
            return queryset.filter(**kwargs)

        if self.value() == '1':
            return queryset.exclude(**kwargs)

        return queryset

